WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_train_meet'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '会车错车', 'kp-trv-train-meet', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "火车会车（错车）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "两车长度之和 = 相对速度 × 会车时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“两列火车相向而行，从车头相遇，到车尾彻底分开，经历了 15 秒”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破局"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这相当于一列静止的火车，另一列火车以两者的速度之和开过去。总路程就是两辆车的长度之和。"}]}, {"type": "katexBlock", "attrs": {"content": "L_A + L_B = (V_A + V_B) \\times T_{会车}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[提取两车的长度 La, Lb] --> B[提取两车的速度 Va, Vb]\nB --> C[套用相遇变形公式: La + Lb = (Va+Vb) * T]\nC --> D[解出 T, 或已知 T 倒推某车的长度]"}}]}$$ AS jsonb), NULL, '会车错车的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "会车错车"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_train_meet", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
